//! Trace-derived sandbox profile for tpm.
//!
//! Initially generated by sandbox_profiler from 1 trace file(s).
//!
//! Observed filesystem accesses:
//! - /etc/ld.so.cache (RO)
//! - /proc/self/comm (RW)
//! - /proc/self/maps (RO)
//! - /usr/lib/x86_64-linux-gnu/libc.so.6 (RO)
//! - /usr/lib/x86_64-linux-gnu/libgcc_s.so.1 (RO)
//! - /usr/lib/x86_64-linux-gnu/libm.so.6 (RO)
//! - /usr/local/ssl/openssl.cnf (RO)
//!
//! Observed network accesses:
//! - None.
//!
//! Observed syscalls:
//! - clone3
//! - close
//! - execve
//! - fcntl
//! - openat
//! - recvmsg
//! - sendmsg
//!
//! Filesystem policy access omissions:
//! - /proc/self/comm is provided by the sandbox's implicit /proc mount.
//! - /proc/self/maps is provided by the sandbox's implicit /proc mount.
//!
//! Syscalls denied by policy but used by the worker:
//! - clone3
//! - execve

use crate::Builder;
use crate::Network;
use crate::Profile;
use crate::Syscalls;

/// Profile derived from observed worker behavior.
pub fn tpm_worker() -> Builder {
    let mut profile = Profile::deny_all()
        .name("tpm_worker")
        .read("/etc")
        .read_exec("/usr/lib");

    if std::path::Path::new("/usr/local/ssl").exists() {
        profile = profile.read("/usr/local/ssl");
    }

    profile
        .syscalls(Syscalls::deny([
            "bpf",
            "chroot",
            "clone3",
            "create_module",
            "delete_module",
            "execve",
            "finit_module",
            "fork",
            "fsconfig",
            "fsmount",
            "fsopen",
            "fspick",
            "init_module",
            "ioperm",
            "iopl",
            "kexec_file_load",
            "kexec_load",
            "mount",
            "mount_setattr",
            "move_mount",
            "open_tree",
            "pivot_root",
            "process_vm_readv",
            "process_vm_writev",
            "ptrace",
            "reboot",
            "setns",
            "umount2",
            "unshare",
            "userfaultfd",
            "waitid",
            "acct",
            "add_key",
            "kcmp",
            "keyctl",
            "request_key",
        ]))
        .network(Network::None)
}

#[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
mod tests {
    use super::*;
    use test_with_tracing::test;

    #[test]
    fn syscall_names_resolve() {
        let profile = tpm_worker().build();
        let Syscalls::Deny(names) = profile.inner.syscalls else {
            panic!("TPM worker must use syscall filtering");
        };
        for name in names {
            assert!(
                crate::nr_for_name(&name).is_some(),
                "TPM worker syscall does not resolve: {name}",
            );
        }
    }
}
